#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; i++) {
        cin >> grid[i];
    }
    long long r1;
    long long c1;
    long long r2;
    long long c2;
    cin >> r1 >> c1 >> r2 >> c2;

    const long long INF = 1000000000000000000LL;
    vector<vector<long long>> dist(h, vector<long long>(w, INF));
    dist[r1 - 1][c1 - 1] = 0;
    typedef pair<long long, pair<int, int>> Item;
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    heap.push({0, {(int)r1 - 1, (int)c1 - 1}});
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    while (!heap.empty()) {
        Item top = heap.top();
        heap.pop();
        long long d = top.first;
        int x = top.second.first, y = top.second.second;
        if (d > dist[x][y]) continue;
        for (int k = 0; k < 4; k++) {
            int a = x, b = y;
            long long steps = 0;
            while (a + dx[k] >= 0 && a + dx[k] < h && b + dy[k] >= 0 && b + dy[k] < w && grid[a + dx[k]][b + dy[k]] == '.') {
                a += dx[k];
                b += dy[k];
                steps++;
            }
            if (steps > 0 && d + steps < dist[a][b]) {
                dist[a][b] = d + steps;
                heap.push({dist[a][b], {a, b}});
            }
        }
    }
    long long answer = dist[r2 - 1][c2 - 1];
    cout << (answer < INF ? answer : -1) << "\n";

    return 0;
}

